import json

def transform(grid):
    """Find all rectangular frames of non-background color and fill their interior with 7."""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Background color (most common)
    bg = 0
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    bg = max(counts, key=counts.get)

    print(f"Background color: {bg}")

    # Find all maximal rectangles using row-by-row scan approach
    # For each row, find horizontal segments of non-bg color
    # Then check if those segments form complete rectangles

    for r in range(h):
        for c in range(w):
            if result[r][c] == bg:
                continue

            color = result[r][c]

            # Find horizontal segment in this row
            left, right = c, c
            while left > 0 and result[r][left-1] == color:
                left -= 1
            while right + 1 < w and result[r][right+1] == color:
                right += 1

            if left >= right:  # Invalid segment
                continue

            # Expand up from the segment
            top = r
            while top > 0 and all(result[top-1][k] == color for k in range(left, right + 1)):
                top -= 1
            top += 1

            # Expand down from the segment
            bottom = r
            while bottom + 1 < h and all(result[bottom+1][k] == color for k in range(left, right + 1)):
                bottom += 1

            if bottom <= top:  # Invalid rectangle
                continue

            # Now verify this is a closed rectangle
            # Check top edge
            if not all(result[top][k] == color for k in range(left, right + 1)):
                continue

            # Check bottom edge
            if not all(result[bottom][k] == color for k in range(left, right + 1)):
                continue

            # Check left edge
            if not all(result[k][left] == color for k in range(top, bottom + 1)):
                continue

            # Check right edge
            if not all(result[k][right] == color for k in range(top, bottom + 1)):
                continue

            # Valid rectangle! Fill interior with 7
            for kr in range(top + 1, bottom):
                for kc in range(left + 1, right):
                    if result[kr][kc] != color:
                        result[kr][kc] = 7

    return result

