import copy

def transform(grid):
    """Find rectangular frames by expanding horizontal edges vertically."""
    result = copy.deepcopy(grid)
    h, w = len(grid), len(grid[0])

    # Track which cells have been processed
    visited = [[False] * w for _ in range(h)]

    for start_r in range(h):
        for start_c in range(w):
            if visited[start_r][start_c] or result[start_r][start_c] in (9, 7):
                continue

            color = result[start_r][start_c]

            # Find full horizontal segment of this color starting from here
            left, right = start_c, start_c
            while right + 1 < w and result[start_r][right + 1] == color:
                right += 1
            # Only start if this is the leftmost cell of the segment
            if right == left:
                while left > 0 and result[start_r][left-1] == color:
                    left -= 1

            # If this segment contains a cell we've already visited, skip
            if visited[start_r][left]:
                # This segment passes through visited cells, mark all as visited
                for c in range(left, right + 1):
                    visited[start_r][c] = True
                continue
            if visited[start_r][right]:
                for c in range(left, right + 1):
                    visited[start_r][c] = True
                continue

            # Expand UP from this segment until we find the top edge
            # The key insight: expand upward while ALL horizontal cells at this row
            # from left to right have the color
            top = start_r
            while top > 0 and all(result[top-1][k] == color for k in range(left, right + 1)):
                top -= 1
            top += 1

            # Mark top row as visited
            for c in range(left, right + 1):
                visited[top][c] = True

            # Expand DOWN from top edge, tracking where left and right vertical edges end
            for drop_r in range(top, h):
                # Check if left edge is solid
                left_solid = all(result[drop_r][left] == color for left_edge_start in range(top, drop_r + 1))
                # Actually simpler: just check current row's left cell
                if not result[drop_r][left] == color:
                    break
                right_edge_ok = result[drop_r][right] == color
                if not right_edge_ok:
                    break

                # Check horizontal segment at this row
                # For middle rows, we only need edges to be solid, not the interior
                # So the horizontal segment can be anything

            # Now verify the bottom edge at row 'bottom'
            bottom = top
            while bottom + 1 < h and all(result[bottom+1][k] == color for k in range(left, right + 1)):
                bottom += 1
            # Now result[bottom] should be solid horizontal
            if not all(result[bottom][k] == color for k in range(left, right + 1)):
                continue  # Not a valid rectangle

            # Verify left and right vertical edges
            left_ok = all(result[r][left] == color for r in range(top, bottom + 1))
            right_ok = all(result[r][right] == color for r in range(top, bottom + 1))

            if not (left_ok and right_ok):
                continue  # Not a valid rectangle

            # Valid frame! Mark all cells as visited
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    visited[r][c] = True

            # Fill interior with 7
            if bottom > top + 1 and right > left + 1:
                for r in range(top + 1, bottom):
                    for c in range(left + 1, right):
                        result[r][c] = 7

    return result

