import copy

def transform(grid):
    """Find all rectangular frames and fill their interiors with 7.

    Rule: Rectangles with borders of a single non-background color have
    their interiors (pixels strictly inside the border) filled with color 7.
    Borders remain unchanged.
    """
    result = copy.deepcopy(grid)
    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]

    for start_r in range(h):
        for start_c in range(w):
            if visited[start_r][start_c] or result[start_r][start_c] in (9, 7):
                continue

            color = result[start_r][start_c]

            # Find full horizontal segment
            left, right = start_c, start_c
            while right + 1 < w and result[start_r][right + 1] == color:
                right += 1
            if right == left:
                while left > 0 and result[start_r][left-1] == color:
                    left -= 1

            # Skip if segment overlaps visited cells
            for c in range(left, right + 1):
                if visited[start_r][c]:
                    for c2 in range(left, right + 1):
                        visited[start_r][c2] = True
                    continue

            # Expand UP to find the top edge
            top = start_r
            while top > 0 and all(result[top-1][k] == color for k in range(left, right + 1)):
                top -= 1

            # Expand DOWN along the vertical edges
            bottom = top
            while bottom + 1 < h:
                if result[bottom + 1][left] != color:
                    break
                if result[bottom + 1][right] != color:
                    break
                bottom += 1

            # Verify bottom edge is solid
            if not all(result[bottom][k] == color for k in range(left, right + 1)):
                continue

            # Mark all cells in this rectangle as visited
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    visited[r][c] = True

            # Fill the INTERIOR (not the border) with 7
            if bottom > top + 1 and right > left + 1:
                for r in range(top + 1, bottom):
                    for c in range(left + 1, right):
                        result[r][c] = 7

    return result

